 $data=[nullable_int($_POST['competition_id']),$homeId,$awayId,$homeLogo,$awayLogo,$home,$away,$_POST['match_type'],nullable_int($_POST['coach_id']),trim($_POST['home_coach_name']),trim($_POST['away_coach_name']),$date,trim($_POST['location']),nullable_int($_POST['score_home']),nullable_int($_POST['score_away']),$_POST['status'],trim($_POST['notes'])];
