 $db->prepare('DELETE FROM match_roster WHERE match_id=?')->execute([$id]);foreach(['home','away'] as $side){foreach(['starters'=>1,'reserves'=>0] as $field=>$starter){$names=preg_split('/\R/',trim($_POST[$side.'_'.$field]??''));foreach($names as $line){$line=trim($line);if($line==='')continue;$db->prepare("INSERT INTO match_roster(match_id,team_side,person_type,person_name,starter) VALUES(?,?,'atleta',?,?)")->execute([$id,$side,$line,$starter]);}}$coach=trim($_POST[$side.'_coach_name']??'');if($coach!=='')$db->prepare("INSERT INTO match_roster(match_id,team_side,person_type,person_name) VALUES(?,?,'tecnico',?)")->execute([$id,$side,$coach]);}
 flash('success','Partida salva.');redirect('matches.php?edit='.$id);
 }catch(Throwable $e){flash('danger',$e->getMessage());redirect('matches.php'.(!empty($_POST['id'])?'?edit='.(int)$_POST['id']:''));}}
