ay_logo_path'])):?><img class="team-logo-preview" src="../<?=e($edit['away_logo_path'])?>"><?php endif;?><label>Técnico<input name="away_coach_name" value="<?=e($edit['away_coach_name']??'')?>"></label><div class="roster-editor-grid"><label>Relacionados / titulares <small>Um atleta por linha</small><textarea name="away_starters" rows="8"><?php foreach($roster['away'] as $p)if($p['person_type']==='atleta' && (int)$p['starter']===1)echo e($p['person_name'])."\n";?></textarea></label><label>Banco de reservas <small>Um atleta por linha</small><textarea name="away_reserves" rows="8"><?php foreach($roster['away'] as $p)if($p['person_type']==='atleta' && (int)$p['starter']===0)echo e($p['person_name'])."\n";?></textarea></label></div></section></div>
