<script>
(()=>{const form=document.getElementById('sumulaForm');if(!form)return;const roster=JSON.parse(form.dataset.roster||'{}'),team=document.getElementById('eventTeam'),type=document.getElementById('eventType');
const fill=(el,items,first)=>{el.innerHTML='<option value="">'+first+'</option>'+items.map(n=>'<option value="'+String(n).replace(/"/g,'&quot;')+'">'+n+'</option>').join('')};
const refresh=()=>{const r=roster[team.value]||{starters:[],reserves:[]};fill(document.getElementById('primaryAthlete'),[...r.starters,...r.reserves],'Selecione');fill(document.getElementById('assistAthlete'),[...r.starters,...r.reserves],'Sem assistência');fill(document.getElementById('subOut'),r.starters,'Selecione o atleta');fill(document.getElementById('subIn'),r.reserves,'Selecione o reserva');toggle()};
const toggle=()=>{const sub=type.value==='substituicao';document.getElementById('normalEventFields').style.display=sub?'none':'grid';document.getElementById('substitutionFields').style.display=sub?'grid':'none';document.querySelectorAll('.assist-field').forEach(x=>x.style.display=type.value==='gol'?'grid':'none')};team.addEventListener('change',refresh);type.addEventListener('change',toggle);refresh();
form.addEventListener('submit',e=>{const sub=type.value==='substituicao';let primary,assist;if(sub){primary=document.getElementById('subOutManual').value.trim()||document.getElementById('subOut').value;assist=document.getElementById('subInManual').value.trim()||document.getElementById('subIn').value;document.getElementById('savedEventType').value='substituicao_saida';if(!primary||!assist){e.preventDefault();alert('Informe o atleta que sai e o atleta que entra.');return;}}else{primary=document.getElementById('primaryManual').value.trim()||document.getElementById('primaryAthlete').value;assist=document.getElementById('assistManual').value.trim()||document.getElementById('assistAthlete').value;document.getElementById('savedEventType').value=type.value;if(!primary){e.preventDefault();alert('Selecione ou informe o atleta.');return;}}document.getElementById('participantName').value=primary;document.getElementById('assistName').value=assist;});})();
</script>
